// Build personalised LinkedIn connection message
const lead = $input.item.json;

const firstName = lead.properties?.['First Name']?.title?.[0]?.plain_text || 'there';
const company = lead.properties?.Company?.rich_text?.[0]?.plain_text || 'your company';
const segment = lead.properties?.Segment?.select?.name || 'agency';
const linkedinUrl = lead.properties?.['LinkedIn URL']?.url || '';

// Choose message variant based on segment
let message = '';

if (segment === 'Agency Owner') {
  message = `Hi ${firstName}, I help marketing agencies automate their client onboarding and lead follow-up so nothing falls through the cracks. Noticed ${company} — would love to connect.`;
} else if (segment === 'Coach / Consultant') {
  message = `Hi ${firstName}, I build automated lead follow-up systems for coaches and consultants so no inquiry ever goes cold. Came across your work — would love to connect.`;
} else if (segment === 'E-commerce') {
  message = `Hi ${firstName}, I help e-commerce founders automate their post-purchase follow-up and support workflows. Saw ${company} and thought there might be a fit — would love to connect.`;
} else if (segment === 'SaaS Founder') {
  message = `Hi ${firstName}, I work with SaaS founders to automate their user onboarding and trial follow-up sequences. Came across ${company} — would love to connect.`;
} else if (segment === 'Real Estate') {
  message = `Hi ${firstName}, I help real estate agencies automate their lead response and follow-up — so no inquiry gets missed. Noticed ${company} and thought it could be relevant. Would love to connect.`;
} else {
  message = `Hi ${firstName}, I help businesses automate their lead follow-up and repetitive ops work. Noticed ${company} — would love to connect.`;
}

return {
  leadId: lead.id,
  firstName,
  company,
  segment,
  linkedinUrl,
  connectionMessage: message,
  channel: 'LinkedIn',
  step: 'Connection Request'
};

// Build personalised cold email
const lead = $input.item.json;

const firstName = lead.properties?.['First Name']?.title?.[0]?.plain_text || 'there';
const company = lead.properties?.Company?.rich_text?.[0]?.plain_text || 'your company';
const segment = lead.properties?.Segment?.select?.name || 'agency';
const email = lead.properties?.Email?.email || '';

let subject = '';
let body = '';

if (segment === 'Agency Owner') {
  subject = 'quick question about your client onboarding';
  body = `Hi ${firstName},

How long does it take your team to onboard a new client right now? From signed contract to fully set up?

Most agencies I talk to spend 2–4 hours on it manually every single time — welcome emails, access setup, project folders, briefs.

I build automated onboarding systems that cut that to under 10 minutes — no manual work, runs itself every time a new client signs.

Would a 15-minute call this week make sense? Happy to show you what one of these looks like for a ${company}-sized agency.

Best,
[Your Name]
IgnAIte | getignaite.com`;
} else if (segment === 'Coach / Consultant') {
  subject = 'quick question about your lead follow-up';
  body = `Hi ${firstName},

How fast does your team typically respond when a new inquiry comes in — a DM, a form submission, a website lead?

Most coaches I speak with lose 30–40% of potential clients simply because follow-up is too slow or gets forgotten in a busy week.

I build automated follow-up systems that respond instantly and keep following up until someone replies — without you doing anything manually.

Would a 15-minute call make sense this week?

Best,
[Your Name]
IgnAIte | getignaite.com`;
} else if (segment === 'E-commerce') {
  subject = 'reducing manual support work at ${company}';
  body = `Hi ${firstName},

How many customer support emails or post-purchase messages does your team handle manually every week at ${company}?

I help e-commerce founders automate the repetitive side of customer comms — order updates, follow-ups, support triage — so the team only handles the things that actually need a human.

Happy to show you a quick demo of what this looks like. 15 minutes — would that be useful?

Best,
[Your Name]
IgnAIte | getignaite.com`;
} else {
  subject = 'quick question about your lead follow-up process';
  body = `Hi ${firstName},

How does ${company} currently handle new lead inquiries — is there a follow-up system in place, or is it mostly manual?

I ask because I work with small businesses to automate exactly that — so no lead goes cold and no follow-up gets forgotten.

Would a quick 15-minute call this week make sense?

Best,
[Your Name]
IgnAIte | getignaite.com`;
}

return {
  leadId: lead.id,
  firstName,
  company,
  segment,
  toEmail: email,
  subject,
  body,
  channel: 'Email',
  step: 'Cold Email 1'
};

// Log outreach action — prepare data for Notion update
const data = $input.item.json;
const today = new Date().toISOString().split('T')[0];

return {
  leadId: data.leadId,
  newStatus: 'Contacted',
  channel: data.channel,
  step: data.step,
  lastContactDate: today,
  followUpDate: getFollowUpDate(5),
  notes: `${data.step} sent on ${today}`
};

function getFollowUpDate(daysAhead) {
  const d = new Date();
  d.setDate(d.getDate() + daysAhead);
  // Skip weekends
  if (d.getDay() === 6) d.setDate(d.getDate() + 2);
  if (d.getDay() === 0) d.setDate(d.getDate() + 1);
  return d.toISOString().split('T')[0];
}

const lead = $input.item.json;

const firstName = lead.properties?.['First Name']?.title?.[0]?.plain_text || 'there';
const company = lead.properties?.Company?.rich_text?.[0]?.plain_text || '';
const channel = lead.properties?.Channel?.select?.name || 'Email';
const step = lead.properties?.['Outreach Step']?.select?.name || 'Cold Email 1';
const email = lead.properties?.Email?.email || '';
const today = new Date().toISOString().split('T')[0];

let nextStep = '';
let subject = '';
let body = '';
let shouldSend = true;

// Determine next follow-up step
if (step === 'Cold Email 1' || step === 'Connection Request') {
  nextStep = 'Follow-Up 1';
  subject = 're: quick question';
  body = `Hi ${firstName},\n\nJust bumping this in case my last message got buried.\n\nI work with businesses like ${company || 'yours'} to automate lead follow-up and client onboarding — so nothing falls through the cracks.\n\nHappy to share a quick 2-minute demo if that sounds relevant. Worth a look?\n\nBest,\n[Your Name]\nIgnAIte | getignaite.com`;
} else if (step === 'Follow-Up 1') {
  nextStep = 'Follow-Up 2';
  subject = 'one last note';
  body = `Hi ${firstName},\n\nLast note from me — I promise!\n\nIf automating your lead follow-up or client onboarding is something on your radar for the next few months, I'd love to show you what we built for similar businesses.\n\nIf the timing's just not right, completely fine — I'll leave it here.\n\nBest,\n[Your Name]\nIgnAIte | getignaite.com`;
} else {
  // Already followed up twice — mark as done
  nextStep = 'Sequence Complete';
  shouldSend = false;
}

// Calculate next follow-up date (5 business days ahead)
function getFollowUpDate(daysAhead) {
  const d = new Date();
  d.setDate(d.getDate() + daysAhead);
  if (d.getDay() === 6) d.setDate(d.getDate() + 2);
  if (d.getDay() === 0) d.setDate(d.getDate() + 1);
  return d.toISOString().split('T')[0];
}

return {
  leadId: lead.id,
  firstName,
  company,
  channel,
  toEmail: email,
  subject,
  body,
  currentStep: step,
  nextStep,
  shouldSend,
  lastContactDate: today,
  followUpDate: shouldSend ? getFollowUpDate(5) : null,
  newStatus: nextStep === 'Sequence Complete' ? 'No Response' : 'Contacted'
};

const leads = $input.all().map(item => item.json);

const stats = {
  totalContacted: 0,
  linkedin: 0,
  email: 0,
  replied: 0,
  callsBooked: 0,
  noResponse: 0,
  sequenceComplete: 0
};

leads.forEach(lead => {
  const status = lead.properties?.Status?.select?.name || '';
  const channel = lead.properties?.Channel?.select?.name || '';

  if (status === 'Contacted' || status === 'No Response' || status === 'Replied' || status === 'Call Booked') {
    stats.totalContacted++;
  }
  if (channel === 'LinkedIn') stats.linkedin++;
  if (channel === 'Email') stats.email++;
  if (status === 'Replied') stats.replied++;
  if (status === 'Call Booked') stats.callsBooked++;
  if (status === 'No Response') stats.noResponse++;
  if (status === 'Sequence Complete') stats.sequenceComplete++;
});

const replyRate = stats.totalContacted > 0 
  ? ((stats.replied + stats.callsBooked) / stats.totalContacted * 100).toFixed(1)
  : 0;

const weekStr = new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });

const summary = `IgnAIte Outreach — Weekly Summary (${weekStr})

📊 THIS WEEK
Total Contacted: ${stats.totalContacted}
LinkedIn: ${stats.linkedin}
Email: ${stats.email}

✅ RESPONSES
Replied: ${stats.replied}
Calls Booked: ${stats.callsBooked}
Reply Rate: ${replyRate}%

📋 PIPELINE
No Response (following up): ${stats.noResponse}
Sequence Complete: ${stats.sequenceComplete}

---
Sent automatically by IgnAIte Outreach System`;

return [{ summary, stats, weekStr }];
